import{_ as o,l as i,o as a,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"调平传感器与空气规","description":"","frontmatter":{"title":"调平传感器与空气规","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/level-sensor-air-gauge.md","filePath":"litho/level-sensor-air-gauge.md","lastUpdated":1789023840000}'),c={name:"litho/level-sensor-air-gauge.md"};function A(_,e,u,E,m,f){const l=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="调平传感器与空气规" tabindex="-1">调平传感器与空气规 <a class="header-anchor" href="#调平传感器与空气规" aria-label="Permalink to &quot;调平传感器与空气规&quot;">​</a></h1><div class="epigraph"><p>晶圆不是平面。调平要在扫描前把局部高度收进焦深；空气规用间隙气流测距，光学高度计看的是另一套反射。</p><footer>—— 对照 level sensor / air gauge；[焦深](/litho/depth-of-focus)、[Focus drilling](/litho/focus-drilling)</footer></div><p><a href="/litho/interferometer-vs-encoder">上一课</a>钉住 XY。缺口是 Z 与倾角：焦深在高 NA 下只有几十纳米量级，形貌必须测。本课钉调平与空气规，焦点伺服细节下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>未调平的片：场内一侧在焦、一侧糊。光学高度计受薄膜栈反射率骗（假高度）；空气规近乎接触气隙，受气孔堵塞和表面多孔骗。只用一种，CDU 会在特定层上爆。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫描前测绘高度图，拟合平移+倾角，扫描中跟踪。空气规沿狭缝或多点。与浸没头的水膜厚度耦合：气隙测量不能破坏液膜。标定用已知台阶片。</p>',7)),(a(),n(p,null,{default:r(()=>[h(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22%E9%AB%98%E5%BA%A6%E5%9B%BE%22%5D%20--%3E%20FIT%5B%22%E5%B9%B3%E7%A7%BB%2B%E5%80%BE%E8%A7%92%22%5D%0A%20%20AG%5B%22%E7%A9%BA%E6%B0%94%E8%A7%84%22%5D%20--%3E%20MAP%0A%20%20OPT%5B%22%E5%85%89%E5%AD%A6%E9%AB%98%E5%BA%A6%22%5D%20--%3E%20MAP%0A%20%20FIT%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E8%B7%9F%E7%84%A6%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p><span class="marginnote">空气规在真空 EUV 上不是同一硬件。本课默认浸没/干式 DUV 气隙；EUV 用光学或电容一类，后课 EUV 再点。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>气隙流量或压力与距离近乎单调，带宽高、对光学常数不敏感。光学测距带宽可以更高、不占机械间隙，但 \\(n\\)、\\(k\\) 变了读数就漂——薄膜课的直接后果。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课把高度图接到焦点传感与形貌的动态跟踪，不只是曝光前一张图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调平是焦深预算的测量前置。</li><li>空气规与光学高度计欺骗源不同，要互校。</li><li>出处：DOF 课；level sensor 通识。</li></ul>',7))])}const g=o(c,[["render",A]]);export{T as __pageData,g as default};
